/* Shared, read-only learning report. The caller owns storage, navigation and consent. */
(function(root){'use strict';
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const n=value=>Number.isFinite(value)?Math.max(0,value):0;
 const copy={
  en:{intro:'See what you have practised and choose what to revisit. This report stays on this device unless you enable sharing.',all:'Game + Practice',gameplay:'Game runs',practice:'Practice',review:'Review only',scope:'Report source',answered:'Questions answered',wrongAttempts:'Wrong attempts',independentFirstTry:'First try, no help',correctWithSupport:'Correct with help',correctAfterRetry:'Correct after retry',revealOnly:'Answer revealed only',topics:'By chapter',topicNote:'Bars show first-try answers without help, out of answered occurrences. Opened questions and reveals without an answer are excluded.',noAnswers:'No answers recorded yet.',notAssessed:'Not assessed',few:'Not enough evidence',evidence:'Answer at least 3 different questions before using a group to guide revision.',progress:'Practice progress',attempts:'Answered',distinct:'Different questions',independent:'First try, no help',standards:'Curriculum detail',sk:'Content Standard (SK)',sp:'Learning Standard (SP)',trend:'Recent sessions',trendNote:'Each bar is one recorded session, ordered by its first capture on this device. Historical saves have no reconstructed answer times.',recommendations:'What to practise next',noRecommendations:'Answer more different questions to receive focused revision suggestions.',basics:'Open Basics',reviewQuestion:'Review',questions:'Question record',question:'Question',status:'Evidence',exports:'Keep a copy',json:'Export JSON',csv:'Export CSV',exportNote:'JSON includes learning records, saved comments and the pending sending queue. CSV contains question-level learning evidence.',syncTitle:'Sharing for future improvements',shareOff:'Enable sharing',shareOn:'Pause sharing',sync:'Send pending records',local:'Saved on this device. Sharing is off.',offline:'Offline. Records stay on this device and will retry when the game is open and the connection returns.',waiting:'Waiting to send. Records remain on this device until the receiver confirms them.',sending:'Sending. Records remain in the queue until confirmed.',received:'Receiver confirmed the current queue.',unavailable:'No receiver is available at this address. Records are still on this device; export a copy or run the collector version.',saveError:'Storage needs attention. Keep this page open and export a copy before leaving.',pending:'Pending',privacy:'Sharing sends question attempts, hint use and comments to the configured receiver. No player name or email is requested. Pausing stops future sends; it does not delete data already received.',reopen:'Sending resumes while the game is open. If you close it offline, reopen the same game address after reconnecting.',diagnostic:'This is a practice review, not a formal assessment or a DSKP performance level.',reviewNote:'Review mode can expose answers. Its evidence is separate from Game + Practice.',answeredCaption:'Occurrences with at least one submitted answer',helpCaption:'A correct answer may also follow a retry; help and retry counts can overlap.',source:'Source',chapter:'Chapter',captured:'First captured',recorded:'recorded',allQuestions:'All 120 question IDs, with their recorded evidence.',viewDetails:'Show details'},
  ms:{intro:'Lihat latihan yang telah dibuat dan pilih perkara untuk diulang kaji. Laporan disimpan pada peranti ini kecuali perkongsian diaktifkan.',all:'Permainan + Latihan',gameplay:'Dalam permainan',practice:'Latihan',review:'Semakan sahaja',scope:'Sumber laporan',answered:'Soalan dijawab',wrongAttempts:'Cubaan salah',independentFirstTry:'Cubaan pertama tanpa bantuan',correctWithSupport:'Betul dengan bantuan',correctAfterRetry:'Betul selepas cuba semula',revealOnly:'Jawapan didedahkan sahaja',topics:'Mengikut bab',topicNote:'Bar menunjukkan jawapan betul pada cubaan pertama tanpa bantuan, berbanding rekod soalan yang dijawab. Soalan yang hanya dibuka atau didedahkan jawapannya tidak dikira.',noAnswers:'Belum ada jawapan direkodkan.',notAssessed:'Belum dinilai',few:'Bukti belum mencukupi',evidence:'Jawab sekurang-kurangnya 3 soalan berbeza sebelum menggunakan sesuatu kumpulan sebagai panduan ulang kaji.',progress:'Perkembangan latihan',attempts:'Dijawab',distinct:'Soalan berbeza',independent:'Cubaan pertama tanpa bantuan',standards:'Perincian kurikulum',sk:'Standard Kandungan (SK)',sp:'Standard Pembelajaran (SP)',trend:'Sesi terkini',trendNote:'Setiap bar mewakili satu sesi mengikut masa rekod pertama disimpan pada peranti ini. Masa menjawab bagi simpanan lama tidak dianggarkan.',recommendations:'Cadangan ulang kaji',noRecommendations:'Jawab lebih banyak soalan berbeza untuk mendapatkan cadangan ulang kaji yang lebih khusus.',basics:'Buka Asas',reviewQuestion:'Semak',questions:'Rekod soalan',question:'Soalan',status:'Bukti',exports:'Simpan salinan',json:'Eksport JSON',csv:'Eksport CSV',exportNote:'JSON mengandungi rekod pembelajaran, komen tersimpan dan rekod yang menunggu penghantaran. CSV mengandungi bukti pembelajaran mengikut soalan.',syncTitle:'Perkongsian untuk penambahbaikan',shareOff:'Aktifkan perkongsian',shareOn:'Jeda perkongsian',sync:'Hantar rekod tertangguh',local:'Disimpan pada peranti ini. Perkongsian belum diaktifkan.',offline:'Tiada sambungan internet. Rekod kekal pada peranti dan akan dicuba semula apabila permainan dibuka serta sambungan pulih.',waiting:'Menunggu penghantaran. Rekod kekal pada peranti sehingga pelayan mengesahkan penerimaannya.',sending:'Sedang dihantar. Rekod kekal dalam giliran sehingga penerimaan disahkan.',received:'Pelayan telah mengesahkan semua rekod dalam giliran semasa.',unavailable:'Pelayan penerima belum tersedia pada alamat ini. Rekod masih ada pada peranti; eksport salinan atau jalankan versi dengan pelayan pengumpulan.',saveError:'Simpanan memerlukan perhatian. Biarkan halaman ini terbuka dan eksport salinan sebelum keluar.',pending:'Menunggu penghantaran',privacy:'Perkongsian menghantar cubaan menjawab, penggunaan petunjuk dan komen kepada pelayan yang ditetapkan. Nama atau e-mel pemain tidak diminta. Jeda menghentikan penghantaran seterusnya; data yang telah diterima tidak dipadam.',reopen:'Penghantaran berjalan semasa permainan dibuka. Jika permainan ditutup ketika tiada internet, buka semula alamat permainan yang sama selepas sambungan pulih.',diagnostic:'Laporan ini ialah panduan latihan, bukan pentaksiran rasmi atau Tahap Penguasaan DSKP.',reviewNote:'Mod semakan boleh mendedahkan jawapan. Rekodnya diasingkan daripada Permainan + Latihan.',answeredCaption:'Rekod soalan dengan sekurang-kurangnya satu jawapan dihantar',helpCaption:'Jawapan betul juga mungkin melibatkan cubaan semula; bilangan bantuan dan cubaan semula boleh bertindih.',source:'Sumber',chapter:'Bab',captured:'Mula direkodkan',recorded:'direkodkan',allQuestions:'Kesemua 120 ID soalan bersama bukti yang telah direkodkan.',viewDetails:'Lihat perincian'}
 };
 function t(language){return copy[language==='ms'?'ms':'en'];}
 function action(label,name,extra='',primary=false){return '<button type="button" class="analytics-btn'+(primary?' primary':'')+'" data-analytics-action="'+name+'" '+extra+'>'+esc(label)+'</button>';}
 function evidence(row,c){return n(row.answered)===0?c.notAssessed:n(row.distinctAnswered)<3?c.few:c.progress;}
 function rate(row){return n(row.answered)?Math.round(n(row.independentFirstTry)/n(row.answered)*100):0;}
 function graph(row,c){const value=rate(row),label=n(row.answered)?n(row.independentFirstTry)+' / '+n(row.answered):c.notAssessed;return '<div class="analytics-bar" role="meter" aria-label="'+esc(c.independent)+'" aria-valuemin="0" aria-valuemax="'+Math.max(1,n(row.answered))+'" aria-valuenow="'+n(row.independentFirstTry)+'" aria-valuetext="'+esc(label)+'"><span style="width:'+value+'%"></span></div><span class="analytics-bar-value">'+esc(label)+'</span>';}
 const destinationCopy={en:{title:'Collection link',label:'Google Apps Script link',save:'Use Google Sheets',local:'Use local receiver',note:'Paste the /exec link supplied by the game organiser. Changing the destination pauses sharing. Enable it again when you are ready.',destination:'Destination',google:'Google Sheets',localName:'Local receiver'},ms:{title:'Pautan pengumpulan',label:'Pautan Google Apps Script',save:'Gunakan Google Sheets',local:'Gunakan penerima setempat',note:'Tampal pautan /exec daripada pengendali permainan. Perkongsian dijeda apabila destinasi ditukar. Aktifkan semula apabila anda bersedia.',destination:'Destinasi',google:'Google Sheets',localName:'Penerima setempat'}};
 function destinationHTML(status,language){const c=destinationCopy[language==='ms'?'ms':'en'],disabled=status.collectionDisabled?'disabled':'';return '<details class="analytics-disclosure analytics-collection"><summary>'+c.title+'</summary><label for="analytics-google-url">'+c.label+'</label><input id="analytics-google-url" data-analytics-google-url type="url" maxlength="400" spellcheck="false" autocomplete="off" aria-describedby="analytics-collection-note" placeholder="https://script.google.com/macros/s/…/exec" value="'+esc(status.destination?.url||'')+'" '+disabled+'><p class="analytics-note" id="analytics-collection-note">'+c.note+'</p><div class="analytics-actions">'+action(c.save,'destination-save',disabled)+action(c.local,'destination-local',disabled)+'</div></details>';}
 function syncHTML(status={},language='en'){
  const dc=destinationCopy[language==='ms'?'ms':'en'],destination=dc.destination+': '+(status.destination?.kind==='google-sheets'?dc.google+' · '+status.destination.url:dc.localName);
  const c=t(language),states={'on-device':c.local,offline:c.offline,waiting:c.waiting,sending:c.sending,received:c.received,unavailable:c.unavailable,'save-error':c.saveError},state=states[status.state]||c.local;
  return '<section class="analytics-sync" aria-label="'+esc(c.syncTitle)+'"><h3>'+c.syncTitle+'</h3><p class="analytics-destination" data-analytics-destination>'+esc(destination)+'</p><p class="analytics-sync-state" role="status" aria-live="polite">'+esc(state)+'</p><p class="analytics-pending">'+c.pending+': <strong data-analytics-pending>'+n(status.pending)+'</strong></p><div class="analytics-actions">'+action(status.enabled?c.shareOn:c.shareOff,'share','aria-pressed="'+!!status.enabled+'" '+(status.collectionDisabled?'disabled':''),!status.enabled)+action(c.sync,'sync',!status.enabled||status.sending||status.collectionDisabled?'disabled':'')+'</div><p class="analytics-note">'+c.privacy+'</p><p class="analytics-note">'+c.reopen+'</p>'+(status.error?'<p class="analytics-error" role="alert">'+esc(status.error)+'</p>':'')+'</section>';
 }
 function standards(rows,c,label){return '<details class="analytics-disclosure"><summary>'+esc(label)+' <span>('+rows.length+')</span></summary><div class="analytics-table-scroll"><table><thead><tr><th scope="col">'+esc(label)+'</th><th scope="col">'+c.attempts+'</th><th scope="col">'+c.independent+'</th><th scope="col">'+c.status+'</th></tr></thead><tbody>'+rows.map(row=>'<tr><th scope="row"><b>'+esc(row.id)+'</b> '+esc(row.label)+'</th><td>'+n(row.answered)+'</td><td>'+n(row.independentFirstTry)+' / '+n(row.answered)+'</td><td>'+evidence(row,c)+'</td></tr>').join('')+'</tbody></table></div></details>';}
 function html({report={},status={},language='en'}={}){
  const c=t(language),totals=report.totals||{},scope=report.scope||'all';
  const topics=report.topics||[],sessions=(report.sessions||[]).slice().sort((a,b)=>String(a.firstCapturedAt).localeCompare(String(b.firstCapturedAt))).slice(-8),recommendations=report.recommendations||[],questions=report.questions||[];
  const scopes=['all','gameplay','practice','review'];
  const metrics=['answered','wrongAttempts','independentFirstTry','correctWithSupport','correctAfterRetry','revealOnly'];
  return '<article class="learning-report" lang="'+(language==='ms'?'ms':'en')+'"><p class="analytics-intro">'+c.intro+'</p><div class="analytics-scopes" role="group" aria-label="'+c.scope+'">'+scopes.map(s=>action(c[s], 'scope','data-scope="'+s+'" aria-pressed="'+(scope===s)+'"')).join('')+'</div>'+(scope==='review'?'<p class="analytics-note">'+c.reviewNote+'</p>':'')+
   '<div class="analytics-metrics">'+metrics.map(k=>'<div class="analytics-metric"><strong data-analytics-metric="'+k+'">'+n(totals[k])+'</strong><span>'+c[k]+'</span></div>').join('')+'</div><p class="analytics-note">'+c.answeredCaption+'. '+c.helpCaption+'</p>'+
   '<section class="analytics-section"><h3>'+c.topics+'</h3><p class="analytics-note">'+c.topicNote+'</p>'+(!n(totals.answered)?'<p class="analytics-empty">'+c.noAnswers+'</p>':'')+'<div class="analytics-topics">'+topics.map(row=>'<div class="analytics-topic"><div class="analytics-topic-title"><h4>'+c.chapter+' '+esc(row.chapter??'')+' · '+esc(row.label||row.topicCode||row.id)+'</h4><span class="analytics-evidence">'+evidence(row,c)+'</span></div><div class="analytics-graph">'+graph(row,c)+'</div><p class="analytics-note">'+c.distinct+': '+n(row.distinctAnswered)+' / '+n(row.totalQuestions)+'</p></div>').join('')+'</div><p class="analytics-note">'+c.evidence+'</p></section>'+
   '<section class="analytics-section"><h3>'+c.recommendations+'</h3>'+(recommendations.length?'<div class="analytics-recommendations">'+recommendations.map(row=>'<div class="analytics-recommendation"><h4>'+esc(row.label)+'</h4><div class="analytics-actions">'+(row.foundationId?action(c.basics,'foundation','data-id="'+esc(row.foundationId)+'"'):'')+(row.questionIds||[]).slice(0,3).map(id=>action(c.reviewQuestion+' '+id,'review','data-id="'+esc(id)+'"')).join('')+'</div></div>').join('')+'</div>':'<p class="analytics-empty">'+c.noRecommendations+'</p>')+'</section>'+
   '<section class="analytics-section"><h3>'+c.standards+'</h3>'+standards(report.contentStandards||[],c,c.sk)+standards(report.learningStandards||[],c,c.sp)+'</section>'+
   '<section class="analytics-section"><h3>'+c.trend+'</h3><p class="analytics-note">'+c.trendNote+'</p>'+(sessions.length?'<div class="analytics-sessions">'+sessions.map(row=>'<div class="analytics-session"><div><b>'+esc(c[row.scope]||row.scope)+'</b><small>'+esc(String(row.firstCapturedAt||'').slice(0,10))+'</small></div><div class="analytics-graph">'+graph(row,c)+'</div></div>').join('')+'</div>':'<p class="analytics-empty">'+c.noAnswers+'</p>')+'</section>'+
   '<details class="analytics-disclosure analytics-question-record"><summary>'+c.questions+'</summary><p class="analytics-note">'+c.allQuestions+'</p><div class="analytics-table-scroll"><table><thead><tr><th scope="col">'+c.question+'</th><th scope="col">'+c.attempts+'</th><th scope="col">'+c.wrongAttempts+'</th><th scope="col">'+c.independent+'</th></tr></thead><tbody>'+questions.map(q=>'<tr><th scope="row">'+action(q.questionId||q.id,'review','data-id="'+esc(q.questionId||q.id)+'"')+'</th><td>'+n(q.answered)+'</td><td>'+n(q.wrongAttempts)+'</td><td>'+n(q.independentFirstTry)+'</td></tr>').join('')+'</tbody></table></div></details>'+
   '<section class="analytics-section"><h3>'+c.exports+'</h3><div class="analytics-actions">'+action(c.json,'export','data-exportformat="json"')+action(c.csv,'export','data-exportformat="csv"')+'</div><p class="analytics-note">'+c.exportNote+'</p></section><div data-analytics-sync>'+syncHTML(status,language)+'</div>'+destinationHTML(status,language)+'<p class="analytics-disclaimer">'+c.diagnostic+'</p></article>';
 }
 const api={html,syncHTML};if(typeof module!=='undefined')module.exports=api;else root.DCAnalyticsUI=api;
})(globalThis);
